\section{Definitions}
\begin{Definition}
		A \textit{vector space} over a field $ F $ is a set $ V $ with two closed operations, \textit{vector addition} or simply \textit{addition} and \textit{scalar multiplication}, that satisfy the following axioms:
		\begin{enumerate}
			\item Associativity of addition;
			\item Commutativity of addition;
			\item Identity element of addition;
			\item Inverse elements of addition;
			\item Compatibility of scalar multiplication with field multiplication;
			\begin{equation}
			a(b \vec{v})=(ab)\vec{v} \nonumber
			\end{equation}
			\item Identity element of scalar multiplication;
			\item Distributivity of scalar multiplication with respect to vector addition;
			\item Distributivity of scalar multiplication with respect to field addition.
		\end{enumerate}
\end{Definition}
\begin{Definition}
	A \textit{subspace} of a vector space $ V $ is a subset $ H $ of $ V $ that has three properties:
	\begin{itemize}
		\item The zero vector of $ V $ is in $ H $.
		\item $ H $ is closed under vector addition.
		\item $ H $ is closed under multiplication by scalars.
	\end{itemize}
	If a subspace only contains the zero vector $ \vec{0} $, it is called a \textit{zero subspace} and written as $ \{\vec{0} \} $.
\end{Definition}	
\begin{Definition}
	Given vectors $ \vec{v}_1,\vec{v}_2,\cdots,\vec{v}_n $ in an arbitrary vector space $ V $ and given scalars $ c_1,c_2,\cdots,c_n $, the vector $ \vec{y} $ defined by
	\begin{equation}
	\vec{y}=c_1 \vec{v}_1+ \cdots + c_n \vec{v}_n \nonumber
	\end{equation}
	is called a \textit{linear combination of $ \vec{v}_1,\vec{v}_2,\cdots,\vec{v}_n  $ using weights $ c_1,c_2,\cdots,c_n $}.
\end{Definition}	
It is easy to verify that the set $ W $ of all linear combinations of $ \vec{v}_1,\vec{v}_2,\cdots,\vec{v}_n  $ is a subspace of $ V $.\newpara
The subspace $ W $ as above is called the subspace \textit{generated} by $ \vec{v}_1,\vec{v}_2,\cdots,\vec{v}_n $. If $ W=V $, then we say that $ \vec{v}_1,\vec{v}_2,\cdots,\vec{v}_n $ \textit{generate} $ V $.
\begin{Definition}
	The \textit{dot product} or \textit{scalar product} of two vectors is defined as the sum of the product of their corresponding components. It has the following properties:
	\begin{enumerate}
		\item The commutativity of dot product.
		\item The distributivity of dot product over vector addition and vice versa.
		\item The associativity of scalar multiplication and dot product.
	\end{enumerate}
Two vectors are \textit{perpendicular} or \textit{orthogonal} if their dot product is zero.
\end{Definition}

\section{Bases}
	\begin{Definition}
	An indexed set of vectors $ \{\vec{v}_1,\cdots,\vec{v}_p \} \in V$ is said to be \textit{linearly independent} if the vector equation
	\begin{equation}
	c_1 \vec{v}_1 + c_2 \vec{v}_2 + \cdots +c_p \vec{v}_p = \vec{0} \nonumber
	\end{equation}
	has only the trivial solution. Otherwise it's said to be \textit{linearly dependent}.
\end{Definition}
\begin{Definition}
	A collection of linearly independent vectors that generated the vector space $ V $ is called a \textit{basis} of $ V $.
\end{Definition}
\begin{Definition}
	Let $ V $ be a vector space and $ \mathscr{B} $ be a basis for it. The \textit{coordinate with respect to basis $ \mathscr{B} $} of an element is a n-tuple of numbers such that the desired element can be expressed with the linear combination of the n-tuple and basis elements. By the definition of basis, the coordinate of any element is unique.
\end{Definition}	
\begin{Definition}
	The \textit{maximal subset of linearly independent elements} is a subset of any collection of vectors of a vector space that adding another element from the original collection that is not in this maximal subset will result in the loss of linearly independence.
\end{Definition}
\begin{Theorem}
	The maximal subset of linearly independent elements of any collection of vectors that generate the vector space is a basis for it.
\end{Theorem}

\section{Dimension of a Vector Space}	
\begin{Theorem}
	Let $ V $ be a vector space over the field $ K $. Let $ \mathscr{B} $ be a basis that has $ m $ elements. Then any collection of more than $ m $ vectors in $ V $ are linearly dependent.
\end{Theorem}	
\begin{proof}
	Let the basis $ \mathscr{B} $ be $ \{\vec{v}_1,\cdots,\vec{v}_m\} $ and the collection of $ n $ vectors($ n>m $) in $ V $ be $ \vec{w}_1,\cdots,\vec{w}_n $. Assume this collection of vectors are linearly independent. Since $ \mathscr{B} $ is a basis, the equation
	\begin{equation}
		\vec{w}_1 = a_1 \vec{v}_1 + \cdots + a_m\vec{v_m} \nonumber
	\end{equation}
	holds for some elements in the field $ K $ that are not all zero. Without loss of generality, we can assume that $ a_1\neq 0 $(otherwise we could just rearrange the equation to make it so). Solve for $ \vec{v}_1 $
	\begin{equation}
		\vec{v}_1 = a_1^{-1}\vec{w}_1 -a_1^{-1}a_2 \vec{v}_2 -\cdots a_1^{-1}a_m \vec{v}_m \nonumber
	\end{equation}
	Then the subspace generated by $ \vec{w}_1,\vec{v}_2,\cdots,\vec{v}_m $ is all of $ V $ since it contains $ \vec{v}_1 $. Now assume by induction that there is an integer $ r $, $ 1 \leqslant r < m $, such that after a suitable renumbering of $ \vec{v}_1,\cdots,\vec{v}_m $, the elements $ \vec{w}_1,\cdots,\vec{w}_r,\vec{v}_{r+1},\cdots,\vec{v}_m $ generate $ V $. Then the equation
	\begin{equation}
		\vec{w}_{r+1}=b_1 \vec{w}_1 + \cdots + b_r \vec{w}_r + c_{r+1}\vec{v}_{r+1}+\cdots + c_m \vec{v}_m \nonumber
	\end{equation}
	holds for some element in $ K $. $ c_{r+1},\cdots, c_m$ can't be all zero, since then we have expressed $ \vec{w}_{r+1} $ as a linear combination of $ \vec{w}_1,\cdots,\vec{w}_r $, contradict out assumption. Without loss of generality, assume that $ c_{r+1} $ is not zero. Repeat the same process when we solve for $ \vec{v}_1 $ to solve for $ \vec{v}_{r+1} $, we then find that $ \vec{v}_{r+1} $ is in the subspace generated by $ \vec{w}_1,\cdots,\vec{w}_{r+1},\vec{v}_{r+2},\cdots,\vec{v}_{m} $. By the induction assumption, these vectors also generate $ V $. Therefore vectors $ \vec{w}_1,\cdots,\vec{w}_m $ generate $ V $, and for $ n>m $ we can expressed $ \vec{w}_n $ as a linear combination of $ \vec{w}_1,\cdots,\vec{w}_m $. The theorem is then proved.
\end{proof}	
\begin{Corollary}
	Any two basis of the same vector space have the same number of elements.
\end{Corollary}
\begin{Definition}
	The number of vectors in a basis is called the \textit{dimension} of this vector space.
\end{Definition}
\begin{Definition}
	The \textit{maximal set of linearly independent elements} of a vector space $ V $ is a collection of linearly independent vectors such that adding extra "outside" vectors would result in the loss of its linearly independence.
\end{Definition}
\begin{Theorem}
	The maximal set of linearly independent elements of a vector space $ V $ is a basis for it.
\end{Theorem}
\begin{proof}
	Let this maximal set be $ \{\vec{v}_1,\cdots,\vec{v}_n \} $ and $ \vec{w} $ be a element of the vector space $ V $. By hypotheses the union of the maximal set and $ \vec{w} $ is linearly dependent, then
	\begin{equation}
		x_0 \vec{w} + x_1 \vec{v}_1 + \cdots + x_n \vec{v}_n = 0 \nonumber
	\end{equation}
	has a nontrivial solution. By the linearly independence of $ \{\vec{v}_1,\cdots,\vec{v}_n \} $, $ x_0 $ is not zero. Then we can solve for $ \vec{w} $
	\begin{equation}
		\vec{w}=- \frac{x_1}{x_0}\vec{v}_1 - \cdots -\frac{x_n}{x_0}\vec{v}_n \nonumber
	\end{equation}
\end{proof}
\begin{Corollary}
	For a vector space of dimension $ n $, any collection of $ n $ linearly independent vectors is a basis for it.
\end{Corollary}
\begin{Corollary}
	Let $ V $ be a vector space and let $ W $ be a subspace for it. If $ \dim W = \dim V $, then $ V=W $.
\end{Corollary}
\begin{Corollary}
	Any linearly independent collections of a vector space can be made to a basis for it by adding some (or $ 0 $) vectors that are/is linearly independent to its elements.
\end{Corollary}
\begin{Theorem}
	The dimension of the subspace $ W $ that does not consist of the zero vector alone of a vector space $ V $ is no greater than $ \dim V $.
\end{Theorem}

\section{Sums and Direct Sums}
\begin{Definition}
	If $ U $ and $ W $ are subspaces of a vector space $ V $, then $ U+W $, the set of all elements $ \vec{u}+\vec{w} $ with $ \vec{u} \in U $ and $ \vec{w} \in W $, is a subspace of $ V $, said to be generated by $ U $ and $ W $, and called the \textit{sum} of $ U $ and $ W $. $ V $ is a \textit{direct sum} of $ U $ and $ W $ if for any $ \vec{v} \in V $ there exist \textbf{unique} elements $ \vec{u}\in U $ an $ \vec{w}\in W $ such that $ \vec{v}=\vec{u}+\vec{w} $. When $ V $ is the direct sum of subspaces $ U $, $ W $, we write 
	\begin{equation}
		V = U \oplus W \nonumber
	\end{equation}
\end{Definition}
\begin{Theorem}
	Let $ V $ be a vector space over the field $ K $, and let $ U $, $ W $ be subspaces. If $ U+W = V $ and $ U\cap W = \{\vec{0} \}$, then $ V = U \oplus W $.
\end{Theorem}
\begin{Theorem}
	Let $ V $ be a finite dimensional vector space over the field $ K $. Let $ W $ be a subspace. Then there exists a subspace $ U $ such that $ V = W \oplus U $.
\end{Theorem}
\begin{Theorem}
	If $ V $ is a finite dimensional vector space and is the direct sum of subspaces $ U $ and $ W $, then
	\begin{equation}
		\dim V = \dim W + \dim U \nonumber
	\end{equation}
\end{Theorem}
\begin{Definition}
	The \textit{direct product} of two vector spaces $ U $ and $ W $ over the field $ K $ is the cartesian product of elements in $ U $ and $ W $, i.e $ (u_1,w_1)\in U \times W $. The vector addition and scalar multiplication are defined to be componentwise.
\end{Definition}
Immediately, the direct product of two vector spaces over the same field is a vector space.
\begin{Theorem}
	\begin{equation}
		\dim (U \times W)=\dim U + \dim W \nonumber
	\end{equation}
\end{Theorem}
\begin{proof}
	For two basis in each space $ \{\vec{u}_1,\cdots,\vec{u}_n \} $ and $ \{\vec{w}_1,\cdots,\vec{w}_m \} $, the collection of vectors in $ U \times W $ consists of $ \{(\vec{u}_1,\vec{0}),\cdots,(\vec{u}_n,\vec{0}),(\vec{0},\vec{w}_1),\cdots,(\vec{0},\vec{w}_m) \} $ is a basis for $ U \times W $ of $ n+m $ elements.
\end{proof}
The notion of direct sum and direct product can be extended to several factors with $ \sum $ and $ \prod $. In this circumstance vector addition and scalar multiplication are also defined to be componentwise.

\chapter{Matrices}

\section{Matrices and Arithmetic Operations on Them}
\begin{Definition}
	A \textit{diagonal matrix} is a square matrix whose nondiagonal entries are zero.
\end{Definition}
\begin{Definition}
	Two matrices are equal if they have the same size and each entries are equal.
\end{Definition}
\begin{Definition}
	The \textit{sum} of two matrices is the sum of each corresponding entries in these two matrices. Thus the sum is defined only when they have the same size.
\end{Definition}
\begin{Definition}
	The \textit{scalar multiple} of a matrix has entries of the product of the scalar and each corresponding original entries.
\end{Definition}
\begin{Theorem}
	The set of matrices of the same size with respect to matrix addition and scalar multiplication over the field of real numbers is a vector space.
\end{Theorem}
\begin{Definition}
	A square matrix is called \textit{lower triangular} if all the entries above the main diagonal are zero. Similarly, a square matrix is called \textit{upper triangular} if all the entries below the main diagonal are zero. A triangular matrix is one that is either lower triangular or upper triangular. A matrix that is both upper and lower triangular is called a \textit{diagonal matrix}.
\end{Definition}
\begin{Definition}
	If $ \matr{A} $ is an $ m \times n $ matrix, and if $ \matr{B} $ is an $ n \times p $ matrix with columns $ \vec{b}_1,\cdots,\vec{b}_p $, then the \textit{product} $ \matr{AB} $ is the $ m \times p $ matrix whose columns are $ \matr{A} \vec{b}_1,\cdots,\matr{A}\vec{b}_p $. Multiplication of matrices corresponds to composition of linear transformations.
\end{Definition}
\begin{Theorem}
	The multiplication has the following properties:
	\begin{itemize}
		\item Associativity of multiplication;
		\item Left distribution;
		\item Right distribution;
		\item Associativity over scalar multiplication;
		\item Identity for matrix multiplication; i.e. If $ \matr{A} $ is a matrix of size $ m \times n $, then
		\begin{equation}
		\matr{I}_m \matr{A} = \matr{A}=\matr{A}\matr{I}_n \nonumber
		\end{equation}
		where $ \matr{I}_n $ is the $ n \times n $  identity matrix.
	\end{itemize}
\end{Theorem}
\begin{Definition}
	In general, matrix multiplication is not commutative and the cancellation law do not hold. When two matrices' multiplication is commutative, they are said to be \textit{commute} with one another. Also, if a product $ \matr{A}\matr{B} $ is the zero matrix, in general it does not mean that either $ \matr{A}=\matr{0} $ or $ \matr{B}=\matr{0} $.
\end{Definition}
\begin{Definition}
	If $ \matr{A} $ is an $ m \times n $ matrix and $ k $ is a positive integer, then $ \matr{A}^k $ denoted the product of $ k $ copies of $ \matr{A} $, i.e. the $ k $th power of $ \matr{A} $. The $ 0 $th power of a matrix is the identity matrix.
\end{Definition}
\begin{Definition}
	If $ \matr{A} $ is an $ m \times n $ matrix, the \textit{transpose} of $ \matr{A} $ is the $ n \times m $ matrix, denoted $ \matr{A}^T $, whose columns are formed from the corresponding rows of $ \matr{A} $.
\end{Definition}
\begin{Definition}
	If $ \matr{A} $ is an $ m \times n $ matrix, the \textit{transpose} of $ \matr{A} $ is the $ n \times m $ matrix, denoted $ \matr{A}^T $, whose columns are formed from the corresponding rows of $ \matr{A} $.
\end{Definition}
\begin{Definition}
	A matrix is said to be \textit{symmetric} if it is equal to its transpose.
\end{Definition}
\begin{Definition}
	The \textit{unit} $ n \times n $ matrix, denoted by $ \matr{I}_n $, is the square matrix having all its components equal to $ 0 $ except the diagonal components, equal to $ 1 $.
\end{Definition}
\begin{Theorem}
	The transpose operation has the following properties:
	\begin{itemize}
		\item $ (\matr{A}^T)^T=\matr{A} $;
		\item $ (\matr{A}+\matr{B})^T = \matr{A}^T+ \matr{B}^T $;
		\item Associativity with scalar multiplication;
		\item $ (\matr{AB})^T = \matr{B}^T \matr{A}^T $, that is, the transpose of a product of arbitrary number of matrices equals the product of their transpose in the reverse order.
	\end{itemize}
\end{Theorem}

\section{The Inverse of a Matrix}
\begin{Definition}
	If $ \matr{A} $ is an $ n \times n $ matrix, then if
	\begin{equation}
	\matr{A}\matr{A}^{-1}=\matr{I}_n\nonumber
	\end{equation}
	we say that $ \matr{A} $ is \textit{invertible} and $ \matr{A}^{-1} $ an \textit{inverse} of $ \matr{A} $. The inverse of a matrix is unique. If a matrix is not invertible, it is called a \textit{singular matrix}.
\end{Definition}

\begin{Theorem}
	A matrix $ \matr{A} $ is invertible only if $ \det(\matr{A}) \neq 0$, and in this case
	\begin{equation}
	\matr{A}^{-1}=\frac{1}{\det(\matr{A})} \adj(\matr{A}) \nonumber
	\end{equation}
\end{Theorem}

\begin{Theorem}
	If $ \matr{A} $ is an invertible $ n \times n $ matrix, then for each $ \vec{b} \in \Real^n $, the equation $ \matr{A}\vec{x}=\vec{b} $ has the unique solution $ \vec{x}=\matr{A}^{-1}\vec{b} $.
\end{Theorem}
\begin{Theorem}
	\begin{itemize}
		\item The inverse of the inverse of a invertible matrix is the matrix itself.
		\item The inverse of the product of arbitrary number of invertible square matrices is the product of the inverse of themselves multiplied in the reverse order.
		\item The transpose of a invertible matrix is also invertible. Moreover, the inverse of a matrix's transpose is the transpose of the matrix's inverse.
	\end{itemize}
\end{Theorem}
\begin{Definition}
	An \textit{elementary matrix} is a matrix obtained by performing a single elementary row operation on a identity matrix.
\end{Definition}
\begin{Theorem}
	If an elementary row operations is performed on an $ m \times n $ matrix $ \matr{A} $, the resulting matrix can be written as $ \matr{EA} $, where the $ m \times m $ matrix $ \matr{E} $ is created by performing the same row operation on $ \matr{I}_m $.
\end{Theorem}
\begin{Theorem}
	Each elementary matrix $ \matr{E} $ is invertible. The inverse of $ \matr{E} $ is the elementary matrix of the same type that transforms $ \matr{E} $ back into $ \matr{I} $.
\end{Theorem}
\begin{Theorem}
	An $ n \times n $ matrix $ \matr{A} $ is invertible iff $ \matr{A} $ is a row equivalent to $ \matr{I}_n $, and in this case, any sequence of elementary row operations that reduces $ \matr{A} $ to $ \matr{I}_n $ also transforms $ \matr{I}_n $ into $ \matr{A}^{-1} $.
\end{Theorem}
\begin{Theorem}[The Invertible Matrix Theorem]
	Let $ \matr{A} $ be a square $ n \times n $ matrix. Then the following statements are equivalent.
	\begin{itemize}
		\item $ \matr{A} $ is an invertible matrix.
		\item $ \matr{A} $ is row equivalent to the $ n \times n $ identity matrix.
		\item $ \matr{A} $ has $ n $ pivot positions. \newpara

		\item The equation $ \matr{A}\vec{x}=\vec{0} $ has only the trivial solution.
		\item The columns of $ \matr{A} $ form a linearly independent set.
		\item The linear transformation $ \vec{x} \mapsto \matr{A}\vec{x} $ is injective.\newpara

		\item The equation $ \matr{A}\vec{x}=\vec{b} $ has at least one solution for each $ \vec{b} $ in $ \Real^n $.
		\item The columns of $ \matr{A} $ span $ \Real^n $.
		\item The linear transformation $ \vec{x} \mapsto \matr{A}\vec{x} $ maps $ \Real^n $ onto $ \Real^n $. \newpara

		\item There is an $ n \times n $ matrix $ \matr{C} $ such that $ \matr{CA}=\matr{I} $.
		\item There is an $ n \times n $ matrix $ \matr{D} $ such that $ \matr{AD}=\matr{I} $.
		\item $ \matr{A}^T $ is an invertible matrix.
		\newpara

		\item The columns of $ \matr{A} $ form a basis of $ \Real^n $.
		\item $ \col \matr{A}=\Real^n $
		\item $ \dim \col \matr{A}=n $
		\item $ \rank \matr{A}=n $
		\item $ \nul \matr{A}=\{\vec{0} \} $
		\item $ \dim \nul \matr{A}=0 $
	\end{itemize}
\end{Theorem}
\begin{Proposition}
	Let $ \matr{A} $ and $ \matr{B} $ be square matrices. If $ \matr{AB}=\matr{I} $, then $ \matr{A} $ and $ \matr{B} $ are both invertible, with $ \matr{B}=\matr{A}^{-1} $ and $ \matr{A}=\matr{B}^{-1}  $
\end{Proposition}
\begin{Definition}
	A linear transformation $ T: \Real^n \to \Real^n $ is \textit{invertible} if there exists a function $ S: \Real^n \to \Real^n $ such that
	\begin{align}
	&(\forall \vec{x}\in \Real^n)\quad S(T(\vec{x}))=\vec{x}\nonumber\\
	&(\forall \vec{x}\in \Real^n)\quad T(S(\vec{x}))=\vec{x}\nonumber
	\end{align}
	and $ S $ is called the \textit{inverse} of $ T $ and denoted $ T^{-1} $.
\end{Definition}
\begin{Theorem}
	A linear transformation is invertible iff its standard matrix is invertible. In this case its inverse is unique.
\end{Theorem}
\begin{Theorem}
	If $ \matr{A} $ is $ m \times n $ and $ \matr{B} $ is $ n \times p $, then
	\begin{align}
	\matr{AB}&=\begin{bmatrix}
	\col_1(\matr{A}) &\col_2(\matr{A}) &\cdots &\col_n(\matr{A}) 
	\end{bmatrix}
	\begin{bmatrix}
	\row_1(\matr{B}) \\
	\row_2(\matr{B}) \\
	\vdots \\
	\row_n(\matr{B}) \\
	\end{bmatrix} \nonumber\\
	&=\col_1(\matr{A})\row_1(\matr{B})+\cdots \col_n(\matr{A})\row_n(\matr{B}) \nonumber
	\end{align}
\end{Theorem}
\begin{Definition}
	A \textit{block matrix} is a partitioned matrix with zero blocks off the main diagonal. Such matrix is invertible iff each block on the diagonal is invertible.
\end{Definition}
\begin{Definition}
	A \textit{factorization} of a matrix is an equation that expresses it as a product of two or more matrices.
\end{Definition}
\begin{Definition}
	An square matrix is said to be \textit{strictly diagonally dominant} if the absolute of each diagonal entry exceeds the sum of the absolute values of the other entries in the same row.
\end{Definition}
\chapter{Linear Mappings}
\begin{Definition}
	Let $ V,W $ be vector spaces over $ K $, and let $ F:V \to W $ be a linear map. The \textit{kennel} of $ F $, denoted $ \Ker F $, is the set of elements $ \vec{v} \in V $ such that $ F(\vec{v}=\vec{0}) $.
\end{Definition}	
The kernel of a linear map on vector space is a subspace of the vector space.
\begin{Proposition}
	The following two conditions are equivalent
	\begin{enumerate}
		\item The kernel of $ F $ is $ \{\vec{0} \} $.
		\item $ F $ is injective.
	\end{enumerate}
\end{Proposition}
